module.exports = "// Global State\nlet allClients = [];\nlet allPlans = [];\nlet allApps = [];\nlet allServers = [];\nlet crmViewMode = 'cards'; // 'cards' ou 'table'\nlet currentReceiptText = '';\nlet currentReceiptPhone = '';\nlet currentQuickClient = null;\nlet currentSettings = {};\nlet ws = null;\n\n// Inicialização da Página\ndocument.addEventListener('DOMContentLoaded', () => {\n  initWebSocket();\n  checkInitialWhatsAppStatus();\n  loadSettings();\n  loadPlans();\n  loadApps();\n  loadServers();\n  loadClients();\n  loadReceipts();\n  updateMenuPreview();\n});\n\nasync function checkInitialWhatsAppStatus() {\n  try {\n    const res = await fetch('/api/whatsapp/status');\n    const data = await res.json();\n    updateWhatsAppUI(data);\n  } catch (e) {\n    console.error('Erro ao verificar status inicial do WhatsApp:', e);\n  }\n}\n\n// === WEBSOCKET PARA QR CODE E STATUS DO WHATSAPP EM TEMPO REAL ===\nfunction initWebSocket() {\n  const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';\n  const wsUrl = `${protocol}//${window.location.host}`;\n\n  ws = new WebSocket(wsUrl);\n\n  ws.onmessage = (event) => {\n    try {\n      const data = JSON.parse(event.data);\n      if (data.type === 'STATUS_UPDATE') {\n        updateWhatsAppUI(data.payload);\n      }\n    } catch (e) {\n      console.error('Erro ao ler WebSocket:', e);\n    }\n  };\n\n  ws.onclose = () => {\n    setTimeout(initWebSocket, 3000);\n  };\n}\n\nfunction updateWhatsAppUI(payload) {\n  const statusBadge = document.getElementById('waStatusBadge');\n  const statusDot = document.getElementById('waStatusDot');\n  const statusText = document.getElementById('waStatusText');\n  const dashWaIcon = document.getElementById('dashWaIcon');\n  const dashWaText = document.getElementById('dashWaText');\n  const qrImg = document.getElementById('qrCodeImg');\n  const qrSpinner = document.getElementById('qrLoadingSpinner');\n  const waConnectStatusText = document.getElementById('waConnectStatusText');\n\n  if (!payload) return;\n\n  if (payload.status === 'connected') {\n    statusDot.className = 'w-3 h-3 rounded-full bg-emerald-500';\n    statusText.innerText = 'WhatsApp Conectado ✅';\n    statusBadge.className = 'flex items-center space-x-2.5 px-4 py-2 rounded-full bg-emerald-100 border border-emerald-300 text-sm font-bold text-emerald-800';\n\n    if (dashWaIcon) {\n      dashWaIcon.className = 'fa-solid fa-circle-check text-4xl text-emerald-600 mb-2';\n      dashWaText.innerText = 'Conectado e Atendendo 24h!';\n    }\n\n    if (qrImg) qrImg.classList.add('hidden');\n    if (qrSpinner) {\n      qrSpinner.classList.remove('hidden');\n      qrSpinner.innerHTML = `\n        <i class=\"fa-solid fa-circle-check text-5xl text-emerald-600 mb-2\"></i>\n        <span class=\"text-sm font-bold text-slate-800\">WhatsApp Conectado com Sucesso!</span>\n      `;\n    }\n    if (waConnectStatusText) waConnectStatusText.innerText = 'Seu robô de vendas está pronto e respondendo aos clientes!';\n\n  } else if (payload.qr) {\n    statusDot.className = 'w-3 h-3 rounded-full bg-yellow-500 animate-pulse';\n    statusText.innerText = 'Escaneie o QR Code 📱';\n    statusBadge.className = 'flex items-center space-x-2.5 px-4 py-2 rounded-full bg-amber-100 border border-amber-300 text-sm font-bold text-amber-900';\n\n    if (dashWaIcon) {\n      dashWaIcon.className = 'fa-solid fa-qrcode text-4xl text-amber-600 mb-2 animate-bounce';\n      dashWaText.innerText = 'Aguardando Escanear QR Code';\n    }\n\n    if (qrSpinner) qrSpinner.classList.add('hidden');\n    if (qrImg) {\n      qrImg.src = payload.qr;\n      qrImg.classList.remove('hidden');\n    }\n    if (waConnectStatusText) waConnectStatusText.innerText = 'Abra o WhatsApp no celular e escaneie o código acima!';\n\n  } else {\n    statusDot.className = 'w-3 h-3 rounded-full bg-red-500';\n    statusText.innerText = 'WhatsApp Desconectado 🔴';\n    statusBadge.className = 'flex items-center space-x-2.5 px-4 py-2 rounded-full bg-red-100 border border-red-300 text-sm font-bold text-red-800';\n\n    if (dashWaIcon) {\n      dashWaIcon.className = 'fa-solid fa-plug-circle-xmark text-4xl text-red-600 mb-2';\n      dashWaText.innerText = 'Desconectado';\n    }\n\n    if (qrImg) qrImg.classList.add('hidden');\n    if (qrSpinner) {\n      qrSpinner.classList.remove('hidden');\n      qrSpinner.innerHTML = `\n        <i class=\"fa-solid fa-circle-notch fa-spin text-4xl text-brand-blue mb-2\"></i>\n        <span class=\"text-xs font-bold\">Gerando novo código QR...</span>\n      `;\n    }\n    if (waConnectStatusText) waConnectStatusText.innerText = 'Iniciando módulo de conexão...';\n  }\n}\n\nasync function reconnectWhatsApp() {\n  try {\n    const res = await fetch('/api/whatsapp/connect', { method: 'POST' });\n    const data = await res.json();\n    alert(data.message || 'Solicitada nova reconexão.');\n  } catch (e) {\n    alert('Erro ao reconectar: ' + e.message);\n  }\n}\n\n// === NAVEGAÇÃO DE ABAS ===\nfunction switchTab(tabId) {\n  document.querySelectorAll('.tab-content').forEach(el => {\n    el.classList.add('hidden');\n    el.style.display = 'none';\n  });\n  document.querySelectorAll('.nav-tab').forEach(el => el.classList.remove('active'));\n  document.querySelectorAll('.mobile-bottom-btn').forEach(el => el.classList.remove('active'));\n\n  const targetTab = document.getElementById(`tab-${tabId}`);\n  const targetBtn = document.getElementById(`tabBtn-${tabId}`);\n  const targetMobBtn = document.getElementById(`mobTab-${tabId}`);\n\n  if (targetTab) {\n    targetTab.classList.remove('hidden');\n    targetTab.style.display = 'block';\n  }\n  if (targetBtn) targetBtn.classList.add('active');\n  if (targetMobBtn) targetMobBtn.classList.add('active');\n\n  if (tabId === 'receipts') {\n    loadReceipts();\n  }\n\n  window.scrollTo({ top: 0, behavior: 'smooth' });\n}\n\n// === CARDS DE PLANOS DE CANAIS COM CORES PERSONALIZADAS ===\nasync function loadPlans() {\n  try {\n    const res = await fetch('/api/plans');\n    allPlans = await res.json();\n    renderPlans(allPlans);\n    populatePlanSelectDropdown();\n  } catch (e) {\n    console.error('Erro ao carregar planos:', e);\n  }\n}\n\nfunction renderPlans(plans) {\n  const container = document.getElementById('plansGrid');\n  if (!container) return;\n  container.innerHTML = '';\n\n  if (!plans || plans.length === 0) {\n    container.innerHTML = `<div class=\"col-span-full text-center py-8 text-slate-500 font-medium bg-white p-6 rounded-2xl border border-[#e2d7c5]\">Nenhum card de plano cadastrado ainda.</div>`;\n    return;\n  }\n\n  plans.forEach(p => {\n    const cardColor = p.color || '#0284c7';\n    const card = document.createElement('div');\n    card.className = 'bg-white rounded-2xl border-2 p-6 shadow-md relative flex flex-col justify-between transition transform hover:-translate-y-1';\n    card.style.borderColor = cardColor;\n\n    card.innerHTML = `\n      <div>\n        <div class=\"flex items-center justify-between mb-3\">\n          <span class=\"text-xs font-extrabold uppercase px-3 py-1 rounded-full text-white shadow-sm\" style=\"background-color: ${cardColor}\">\n            Plano IPTV\n          </span>\n          <button onclick=\"deletePlan(${p.id})\" class=\"text-slate-400 hover:text-red-600 transition p-1\" title=\"Excluir Plano\">\n            <i class=\"fa-solid fa-trash text-base\"></i>\n          </button>\n        </div>\n\n        <h3 class=\"text-xl font-extrabold text-slate-900 mb-2\">${p.name}</h3>\n        <p class=\"text-3xl font-extrabold mb-4\" style=\"color: ${cardColor}\">\n          R$ ${parseFloat(p.price).toFixed(2)} <span class=\"text-xs text-slate-500 font-normal\">/mês</span>\n        </p>\n\n        <p class=\"text-sm text-slate-600 mb-4 font-medium leading-relaxed\">\n          ${p.description || 'Canais em HD, FHD e 4K + Filmes e Séries atualizados'}\n        </p>\n      </div>\n\n      <div class=\"pt-4 border-t border-slate-100 flex items-center justify-between text-xs text-slate-500 font-bold\">\n        <span><i class=\"fa-solid fa-check text-emerald-600 mr-1\"></i> Liberação Imediata</span>\n        <span><i class=\"fa-solid fa-bolt text-amber-500 mr-1\"></i> Suporte 24h</span>\n      </div>\n    `;\n\n    container.appendChild(card);\n  });\n}\n\nfunction populatePlanSelectDropdown() {\n  const select = document.getElementById('clientPlanSelect');\n  if (!select) return;\n  select.innerHTML = '<option value=\"\">-- Selecionar da Lista de Planos --</option>';\n\n  allPlans.forEach(p => {\n    const opt = document.createElement('option');\n    opt.value = p.name;\n    opt.dataset.price = p.price;\n    opt.innerText = `${p.name} - R$ ${parseFloat(p.price).toFixed(2)}`;\n    select.appendChild(opt);\n  });\n}\n\nfunction onClientPlanSelectChange() {\n  const select = document.getElementById('clientPlanSelect');\n  const selectedOpt = select.options[select.selectedIndex];\n  if (selectedOpt && selectedOpt.dataset.price) {\n    document.getElementById('clientPlanName').value = selectedOpt.value;\n    document.getElementById('clientPrice').value = selectedOpt.dataset.price;\n  }\n}\n\nasync function saveNewPlan(e) {\n  e.preventDefault();\n  const name = document.getElementById('newPlanName').value.trim();\n  const price = parseFloat(document.getElementById('newPlanPrice').value);\n  const color = document.getElementById('newPlanColor').value;\n  const description = document.getElementById('newPlanDesc').value.trim();\n\n  if (!name || isNaN(price)) {\n    alert('Preencha o nome e valor do plano.');\n    return;\n  }\n\n  try {\n    await fetch('/api/plans', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ name, price, color, description })\n    });\n    document.getElementById('newPlanName').value = '';\n    document.getElementById('newPlanPrice').value = '';\n    document.getElementById('newPlanDesc').value = '';\n    loadPlans();\n    alert('🎨 Novo card de plano cadastrado com sucesso!');\n  } catch (err) {\n    alert('Erro ao salvar plano: ' + err.message);\n  }\n}\n\nasync function deletePlan(id) {\n  if (!confirm('Deseja excluir este plano de canais?')) return;\n  try {\n    await fetch(`/api/plans/${id}`, { method: 'DELETE' });\n    loadPlans();\n  } catch (err) {\n    alert('Erro ao excluir plano: ' + err.message);\n  }\n}\n\n// === GERENCIAMENTO DE APPLICATIVOS E SERVIDORES ===\nasync function loadApps() {\n  try {\n    const res = await fetch('/api/apps');\n    allApps = await res.json();\n    renderApps(allApps);\n    populateAppDropdown();\n  } catch (e) {\n    console.error('Erro ao carregar apps:', e);\n  }\n}\n\nfunction renderApps(apps) {\n  const container = document.getElementById('appsList');\n  if (!container) return;\n  container.innerHTML = '';\n\n  if (!apps || apps.length === 0) {\n    container.innerHTML = `<div class=\"p-3 text-center text-xs text-slate-500\">Nenhum aplicativo cadastrado.</div>`;\n    return;\n  }\n\n  apps.forEach(a => {\n    const item = document.createElement('div');\n    item.className = 'p-3 rounded-xl bg-[#f7f3ea] border border-[#e2d7c5] flex items-center justify-between text-sm font-bold text-slate-900';\n    item.innerHTML = `\n      <span class=\"flex items-center gap-2\">\n        <i class=\"fa-solid fa-mobile-screen text-purple-600\"></i> ${a.name}\n      </span>\n      <button onclick=\"deleteApp(${a.id})\" class=\"text-slate-400 hover:text-red-600 transition p-1\"><i class=\"fa-solid fa-trash\"></i></button>\n    `;\n    container.appendChild(item);\n  });\n}\n\nfunction populateAppDropdown() {\n  const select = document.getElementById('clientAppSelect');\n  if (!select) return;\n  select.innerHTML = '<option value=\"\">-- Nenhum App Selecionado --</option>';\n\n  allApps.forEach(a => {\n    const opt = document.createElement('option');\n    opt.value = a.name;\n    opt.innerText = a.name;\n    select.appendChild(opt);\n  });\n}\n\nasync function saveNewApp(e) {\n  e.preventDefault();\n  const name = document.getElementById('newAppName').value.trim();\n  if (!name) return;\n\n  try {\n    await fetch('/api/apps', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ name })\n    });\n    document.getElementById('newAppName').value = '';\n    loadApps();\n    alert('📱 Aplicativo cadastrado com sucesso!');\n  } catch (e) {\n    alert('Erro ao cadastrar aplicativo: ' + e.message);\n  }\n}\n\nasync function deleteApp(id) {\n  if (!confirm('Deseja excluir este aplicativo?')) return;\n  try {\n    await fetch(`/api/apps/${id}`, { method: 'DELETE' });\n    loadApps();\n  } catch (e) {\n    alert('Erro ao excluir app: ' + e.message);\n  }\n}\n\nasync function loadServers() {\n  try {\n    const res = await fetch('/api/servers');\n    allServers = await res.json();\n    renderServers(allServers);\n    populateServerDropdown();\n  } catch (e) {\n    console.error('Erro ao carregar servidores:', e);\n  }\n}\n\nfunction renderServers(servers) {\n  const container = document.getElementById('serversList');\n  if (!container) return;\n  container.innerHTML = '';\n\n  if (!servers || servers.length === 0) {\n    container.innerHTML = `<div class=\"p-3 text-center text-xs text-slate-500\">Nenhum servidor cadastrado.</div>`;\n    return;\n  }\n\n  servers.forEach(s => {\n    const item = document.createElement('div');\n    item.className = 'p-3 rounded-xl bg-[#f7f3ea] border border-[#e2d7c5] flex items-center justify-between text-sm font-bold text-slate-900';\n    item.innerHTML = `\n      <span class=\"flex items-center gap-2\">\n        <i class=\"fa-solid fa-server text-brand-blue\"></i> ${s.name}\n      </span>\n      <button onclick=\"deleteServer(${s.id})\" class=\"text-slate-400 hover:text-red-600 transition p-1\"><i class=\"fa-solid fa-trash\"></i></button>\n    `;\n    container.appendChild(item);\n  });\n}\n\nfunction populateServerDropdown() {\n  const select = document.getElementById('clientServerSelect');\n  if (!select) return;\n  select.innerHTML = '<option value=\"\">-- Nenhum Servidor Selecionado --</option>';\n\n  allServers.forEach(s => {\n    const opt = document.createElement('option');\n    opt.value = s.name;\n    opt.innerText = s.name;\n    select.appendChild(opt);\n  });\n}\n\nasync function saveNewServer(e) {\n  e.preventDefault();\n  const name = document.getElementById('newServerName').value.trim();\n  if (!name) return;\n\n  try {\n    await fetch('/api/servers', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ name })\n    });\n    document.getElementById('newServerName').value = '';\n    loadServers();\n    alert('🖥 Servidor cadastrado com sucesso!');\n  } catch (e) {\n    alert('Erro ao cadastrar servidor: ' + e.message);\n  }\n}\n\nasync function deleteServer(id) {\n  if (!confirm('Deseja excluir este servidor?')) return;\n  try {\n    await fetch(`/api/servers/${id}`, { method: 'DELETE' });\n    loadServers();\n  } catch (e) {\n    alert('Erro ao excluir servidor: ' + e.message);\n  }\n}\n\n// === CONFIGURAÇÕES DO SISTEMA & IA ===\nasync function loadSettings() {\n  try {\n    const res = await fetch('/api/settings');\n    currentSettings = await res.json();\n\n    if (currentSettings.company_name) {\n      document.getElementById('companyNameInput').value = currentSettings.company_name;\n      document.getElementById('headerCompanyName').innerText = currentSettings.company_name;\n    }\n    if (currentSettings.bot_enabled) {\n      document.getElementById('botEnabledSelect').value = currentSettings.bot_enabled;\n    }\n    if (currentSettings.gemini_api_key) {\n      document.getElementById('geminiApiKey').value = currentSettings.gemini_api_key;\n    }\n    if (currentSettings.system_prompt) {\n      document.getElementById('systemPromptText').value = currentSettings.system_prompt;\n    }\n    if (currentSettings.test_duration) {\n      document.getElementById('testDuration').value = currentSettings.test_duration;\n    }\n    if (currentSettings.pix_key) {\n      document.getElementById('pixKeyInput').value = currentSettings.pix_key;\n    }\n    if (currentSettings.company_logo) {\n      updateLogoPreviewUI(currentSettings.company_logo);\n    }\n\n    updateMenuPreview();\n  } catch (e) {\n    console.error('Erro ao carregar configurações:', e);\n  }\n}\n\nasync function uploadLogoFile(event) {\n  const file = event.target.files[0];\n  if (!file) return;\n\n  if (file.size > 10 * 1024 * 1024) {\n    alert('A imagem é muito grande. Por favor escolha uma imagem de até 10MB.');\n    return;\n  }\n\n  const reader = new FileReader();\n  reader.onload = async (e) => {\n    const base64Data = e.target.result;\n\n    try {\n      const res = await fetch('/api/upload-logo', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ imageBase64: base64Data, filename: file.name })\n      });\n      const data = await res.json();\n      if (data.success) {\n        currentSettings.company_logo = data.logo_url;\n        updateLogoPreviewUI(data.logo_url);\n        alert('🖼️ Foto da Logo da empresa enviada e salva com sucesso!');\n      } else {\n        alert('Erro ao enviar foto da logo: ' + (data.error || 'Erro desconhecido'));\n      }\n    } catch (err) {\n      alert('Erro ao fazer upload da logo: ' + err.message);\n    }\n  };\n  reader.readAsDataURL(file);\n}\n\nfunction updateLogoPreviewUI(url) {\n  const previewImg = document.getElementById('logoPreviewImg');\n  const previewIcon = document.getElementById('logoPreviewIcon');\n  const companyLogoInput = document.getElementById('companyLogoInput');\n  const headerLogoImg = document.getElementById('headerLogoImg');\n  const headerLogoIcon = document.getElementById('headerLogoIcon');\n\n  if (companyLogoInput) companyLogoInput.value = url || '';\n\n  if (url && url.trim().length > 3) {\n    if (previewImg) {\n      previewImg.src = url;\n      previewImg.classList.remove('hidden');\n    }\n    if (previewIcon) previewIcon.classList.add('hidden');\n\n    if (headerLogoImg) {\n      headerLogoImg.src = url;\n      headerLogoImg.classList.remove('hidden');\n    }\n    if (headerLogoIcon) headerLogoIcon.classList.add('hidden');\n  } else {\n    if (previewImg) previewImg.classList.add('hidden');\n    if (previewIcon) previewIcon.classList.remove('hidden');\n\n    if (headerLogoImg) headerLogoImg.classList.add('hidden');\n    if (headerLogoIcon) headerLogoIcon.classList.remove('hidden');\n  }\n}\n\nasync function removeLogoFile() {\n  if (!confirm('Deseja remover a foto da logo da empresa?')) return;\n  try {\n    await fetch('/api/settings', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ settings: { company_logo: '' } })\n    });\n    currentSettings.company_logo = '';\n    updateLogoPreviewUI('');\n    alert('Foto da logo removida com sucesso.');\n  } catch (e) {\n    alert('Erro ao remover logo: ' + e.message);\n  }\n}\n\nasync function saveCompanySettings(e) {\n  e.preventDefault();\n  const settings = {\n    company_name: document.getElementById('companyNameInput').value.trim(),\n    bot_enabled: document.getElementById('botEnabledSelect').value\n  };\n\n  try {\n    await fetch('/api/settings', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ settings })\n    });\n    alert('Dados da empresa salvos com sucesso!');\n    loadSettings();\n  } catch (e) {\n    alert('Erro ao salvar empresa: ' + e.message);\n  }\n}\n\nasync function saveAiSettings(e) {\n  e.preventDefault();\n  const settings = {\n    gemini_api_key: document.getElementById('geminiApiKey').value.trim(),\n    system_prompt: document.getElementById('systemPromptText').value,\n    test_duration: document.getElementById('testDuration').value.trim(),\n    pix_key: document.getElementById('pixKeyInput').value.trim(),\n    company_logo: document.getElementById('companyLogoInput') ? document.getElementById('companyLogoInput').value.trim() : ''\n  };\n\n  try {\n    await fetch('/api/settings', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ settings })\n    });\n    alert('Configurações salvas com sucesso!');\n    loadSettings();\n  } catch (e) {\n    alert('Erro ao salvar IA: ' + e.message);\n  }\n}\n\nasync function appendQuickInfoToPrompt() {\n  const input = document.getElementById('quickPromptInfoInput');\n  const text = input ? input.value.trim() : '';\n\n  if (!text) {\n    alert('Por favor, digite a informação que deseja adicionar ao prompt.');\n    return;\n  }\n\n  const textarea = document.getElementById('systemPromptText');\n  const currentPrompt = textarea ? textarea.value : '';\n  const dateStr = new Date().toLocaleDateString('pt-BR');\n  \n  const newPrompt = currentPrompt + `\\n\\n📌 [Informação Adicionada em ${dateStr}]:\\n- ${text}`;\n  textarea.value = newPrompt;\n\n  const settings = { system_prompt: newPrompt };\n\n  try {\n    await fetch('/api/settings', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ settings })\n    });\n    alert('✨ Nova informação anexada com sucesso ao Prompt Geral do sistema!');\n    input.value = '';\n    loadSettings();\n  } catch (e) {\n    alert('Erro ao salvar no prompt: ' + e.message);\n  }\n}\n\nfunction updateMenuPreview() {\n  const company = currentSettings.company_name || 'IPTV Premium';\n  const preview = `🤖 *Atendimento Automático - ${company}*\n\nOlá! Seja muito bem-vindo(a)! 👋\nSou o assistente virtual da *${company}*.\n\nComo posso te ajudar hoje? Por favor, escolha uma das opções abaixo digitando apenas o *número* correspondente:\n\n1️⃣ *Consultar Vencimento & Chave Pix*\n2️⃣ *Solicitar Teste Grátis*\n3️⃣ *Ver Planos e Preços*\n4️⃣ *Tirar Dúvidas com Atendente (IA)*\n\n_Digite o número da opção desejada:_`;\n  \n  const box = document.getElementById('menuPreviewBox');\n  if (box) box.innerText = preview;\n}\n\n// === CLIENTES (CRM - MODO CARDS E MODO TABELA) ===\nasync function loadClients() {\n  try {\n    const res = await fetch('/api/clients');\n    if (!res.ok) throw new Error('Erro HTTP na API /api/clients: ' + res.status);\n    const data = await res.json();\n    allClients = Array.isArray(data) ? data : [];\n    renderClients(allClients);\n    updateDashboardStats(allClients);\n  } catch (e) {\n    console.error('Erro ao carregar clientes:', e);\n    allClients = Array.isArray(allClients) ? allClients : [];\n    renderClients(allClients);\n  }\n}\n\nfunction setCrmViewMode(mode) {\n  crmViewMode = mode;\n\n  const btnCards = document.getElementById('viewBtnCards');\n  const btnTable = document.getElementById('viewBtnTable');\n  const cardsGrid = document.getElementById('clientsCardsGrid');\n  const tableView = document.getElementById('clientsTableView');\n\n  if (mode === 'cards') {\n    btnCards.className = 'px-4 py-2 rounded-lg text-sm font-bold transition bg-brand-blue text-white shadow-sm';\n    btnTable.className = 'px-4 py-2 rounded-lg text-sm font-bold text-slate-700 hover:text-slate-900 transition';\n    cardsGrid.classList.remove('hidden');\n    tableView.classList.add('hidden');\n  } else {\n    btnTable.className = 'px-4 py-2 rounded-lg text-sm font-bold transition bg-brand-blue text-white shadow-sm';\n    btnCards.className = 'px-4 py-2 rounded-lg text-sm font-bold text-slate-700 hover:text-slate-900 transition';\n    tableView.classList.remove('hidden');\n    cardsGrid.classList.add('hidden');\n  }\n\n  filterClients();\n}\n\nfunction renderClients(clients) {\n  renderClientCards(clients);\n  renderClientTable(clients);\n}\n\nfunction formatWaUrl(phone) {\n  if (!phone) return '#';\n  let clean = phone.replace(/\\D/g, '');\n  if (clean.length === 10 || clean.length === 11) {\n    clean = '55' + clean;\n  }\n  return `https://wa.me/${clean}`;\n}\n\n// RENDERIZADOR 1: MODO CARDS (CARDS INDIVIDUAIS COM TODAS AS INFORMAÇÕES DO CLIENTE)\nfunction renderClientCards(clients) {\n  const grid = document.getElementById('clientsCardsGrid');\n  if (!grid) return;\n  grid.innerHTML = '';\n\n  if (!clients || clients.length === 0) {\n    grid.innerHTML = `<div class=\"col-span-full text-center py-10 text-slate-500 font-medium bg-white p-6 rounded-2xl border border-[#e2d7c5]\">Nenhum cliente encontrado.</div>`;\n    return;\n  }\n\n  const today = new Date().toISOString().split('T')[0];\n\n  clients.forEach(c => {\n    const card = document.createElement('div');\n    card.className = 'bg-white border-2 border-[#e2d7c5] rounded-3xl p-6 shadow-md relative flex flex-col justify-between transition transform hover:-translate-y-1';\n\n    const due = new Date(c.due_date + 'T00:00:00');\n    const now = new Date(today + 'T00:00:00');\n    const diffDays = Math.ceil((due - now) / (1000 * 60 * 60 * 24));\n\n    let statusBadge = '';\n    if (diffDays < 0) {\n      statusBadge = `<span class=\"bg-red-100 text-red-700 border border-red-300 px-3 py-1 rounded-full text-xs font-extrabold\">🔴 Vencido (${Math.abs(diffDays)}d atrás)</span>`;\n    } else if (diffDays <= 3) {\n      statusBadge = `<span class=\"bg-orange-100 text-orange-800 border border-orange-300 px-3 py-1 rounded-full text-xs font-extrabold\">🟠 Vence em ${diffDays} dia(s)</span>`;\n    } else {\n      statusBadge = `<span class=\"bg-emerald-100 text-emerald-800 border border-emerald-300 px-3 py-1 rounded-full text-xs font-extrabold\">🟢 Ativo (${diffDays}d restantes)</span>`;\n    }\n\n    const dueDateFormatted = c.due_date ? c.due_date.split('-').reverse().join('/') : '-';\n    const code = c.client_code || `#${1000 + c.id}`;\n    const waLink = formatWaUrl(c.phone);\n\n    card.innerHTML = `\n      <div>\n        <!-- Card Header: Código e Status Badge -->\n        <div class=\"flex items-center justify-between mb-3\">\n          <span class=\"font-mono font-extrabold text-brand-orange text-sm bg-orange-50 border border-orange-200 px-2.5 py-1 rounded-lg\">\n            ${code}\n          </span>\n          ${statusBadge}\n        </div>\n\n        <!-- Nome do Cliente & Telefone -->\n        <h3 class=\"text-xl font-extrabold text-slate-900 tracking-tight\">${c.name}</h3>\n        <p class=\"text-sm font-mono text-slate-600 mb-4 flex items-center gap-1.5 font-bold\">\n          <a href=\"${waLink}\" target=\"_blank\" class=\"hover:text-emerald-600 text-slate-800 flex items-center gap-1.5\">\n            <i class=\"fa-brands fa-whatsapp text-emerald-600 text-base\"></i> ${c.phone}\n          </a>\n        </p>\n\n        <!-- Informações do Plano & Valor -->\n        <div class=\"bg-[#f7f3ea] p-3.5 rounded-2xl border border-[#e2d7c5] mb-4 space-y-2\">\n          <div class=\"flex items-center justify-between\">\n            <span class=\"text-xs font-bold text-slate-500 uppercase\">Plano Contratado</span>\n            <span class=\"text-sm font-extrabold text-brand-orange\">R$ ${parseFloat(c.price).toFixed(2)}</span>\n          </div>\n          <p class=\"font-extrabold text-slate-900 text-base\">${c.plan_name}</p>\n\n          <!-- Badges de App e Servidor -->\n          <div class=\"flex flex-wrap gap-2 pt-1 border-t border-[#e2d7c5]\">\n            <span class=\"text-xs font-bold bg-purple-100 text-purple-800 border border-purple-200 px-2.5 py-1 rounded-lg flex items-center gap-1\">\n              <i class=\"fa-solid fa-mobile-screen-button\"></i> ${c.app_name || 'App Não Informado'}\n            </span>\n            <span class=\"text-xs font-bold bg-sky-100 text-sky-800 border border-sky-200 px-2.5 py-1 rounded-lg flex items-center gap-1\">\n              <i class=\"fa-solid fa-server\"></i> ${c.server_name || 'Servidor Não Informado'}\n            </span>\n          </div>\n        </div>\n\n        <!-- Data de Vencimento e Notas -->\n        <div class=\"flex items-center justify-between text-xs font-bold text-slate-700 mb-4\">\n          <span>🗓 Vencimento: <b class=\"text-slate-900 text-sm\">${dueDateFormatted}</b></span>\n          ${c.notes ? `<span class=\"text-slate-500 font-normal truncate max-w-[140px]\">${c.notes}</span>` : ''}\n        </div>\n      </div>\n\n      <!-- Card Actions -->\n      <div class=\"pt-4 border-t border-slate-100 flex items-center justify-between gap-2\">\n        <button onclick=\"renewClient(${c.id})\" class=\"flex-1 bg-emerald-600 hover:bg-emerald-700 text-white font-extrabold text-xs py-2.5 px-3 rounded-xl shadow-sm transition flex items-center justify-center gap-1\">\n          <i class=\"fa-solid fa-circle-check\"></i> Dar Baixa\n        </button>\n\n        <button onclick=\"openQuickMessageModal(${c.id})\" class=\"flex-1 bg-brand-blue hover:bg-sky-700 text-white font-extrabold text-xs py-2.5 px-3 rounded-xl shadow-sm transition flex items-center justify-center gap-1\">\n          <i class=\"fa-brands fa-whatsapp\"></i> Aviso\n        </button>\n\n        <button onclick=\"editClient(${c.id})\" class=\"text-slate-600 hover:text-brand-blue p-2 font-bold text-base\" title=\"Editar\"><i class=\"fa-solid fa-pen-to-square\"></i></button>\n        <button onclick=\"deleteClient(${c.id})\" class=\"text-slate-600 hover:text-red-600 p-2 font-bold text-base\" title=\"Excluir\"><i class=\"fa-solid fa-trash\"></i></button>\n      </div>\n    `;\n\n    grid.appendChild(card);\n  });\n}\n\n// RENDERIZADOR 2: MODO TABELA (LISTAGEM TRADICIONAL)\nfunction renderClientTable(clients) {\n  const tbody = document.getElementById('clientsTableBody');\n  if (!tbody) return;\n  tbody.innerHTML = '';\n\n  if (!clients || clients.length === 0) {\n    tbody.innerHTML = `<tr><td colspan=\"8\" class=\"text-center py-8 text-slate-500 font-medium\">Nenhum cliente encontrado.</td></tr>`;\n    return;\n  }\n\n  const today = new Date().toISOString().split('T')[0];\n\n  clients.forEach(c => {\n    const tr = document.createElement('tr');\n    tr.className = 'hover:bg-amber-50/80 transition border-b border-[#e2d7c5]';\n\n    const due = new Date(c.due_date + 'T00:00:00');\n    const now = new Date(today + 'T00:00:00');\n    const diffDays = Math.ceil((due - now) / (1000 * 60 * 60 * 24));\n\n    let statusBadge = '';\n    if (diffDays < 0) {\n      statusBadge = `<span class=\"bg-red-100 text-red-700 border border-red-300 px-3 py-1 rounded-full text-xs font-extrabold\">🔴 Vencido (${Math.abs(diffDays)}d atrás)</span>`;\n    } else if (diffDays <= 3) {\n      statusBadge = `<span class=\"bg-orange-100 text-orange-800 border border-orange-300 px-3 py-1 rounded-full text-xs font-extrabold\">🟠 Vence em ${diffDays} dia(s)</span>`;\n    } else {\n      statusBadge = `<span class=\"bg-emerald-100 text-emerald-800 border border-emerald-300 px-3 py-1 rounded-full text-xs font-extrabold\">🟢 Ativo (${diffDays}d restantes)</span>`;\n    }\n\n    const dueDateFormatted = c.due_date ? c.due_date.split('-').reverse().join('/') : '-';\n    const code = c.client_code || `#${1000 + c.id}`;\n    const waLink = formatWaUrl(c.phone);\n\n    tr.innerHTML = `\n      <td class=\"py-4 px-4 font-mono font-extrabold text-brand-orange text-sm\">\n        ${code}\n      </td>\n      <td class=\"py-4 px-4 font-bold text-slate-900 text-base\">\n        ${c.name}\n        ${c.notes ? `<p class=\"text-xs text-slate-500 font-normal mt-0.5\">${c.notes}</p>` : ''}\n      </td>\n      <td class=\"py-4 px-4 text-slate-700 font-mono text-sm\">\n        <a href=\"${waLink}\" target=\"_blank\" class=\"hover:text-emerald-600 font-bold flex items-center gap-1.5 text-slate-800\">\n          <i class=\"fa-brands fa-whatsapp text-emerald-600 text-base\"></i> ${c.phone}\n        </a>\n      </td>\n      <td class=\"py-4 px-4 text-slate-800\">\n        <span class=\"font-bold text-slate-900\">${c.plan_name}</span>\n        <p class=\"text-sm text-brand-orange font-extrabold\">R$ ${parseFloat(c.price).toFixed(2)}</p>\n      </td>\n      <td class=\"py-4 px-4 text-xs font-bold text-slate-700\">\n        <span class=\"block text-purple-700\">📱 ${c.app_name || '-'}</span>\n        <span class=\"block text-sky-700\">🖥 ${c.server_name || '-'}</span>\n      </td>\n      <td class=\"py-4 px-4 font-bold text-slate-900\">\n        🗓 ${dueDateFormatted}\n      </td>\n      <td class=\"py-4 px-4\">${statusBadge}</td>\n      <td class=\"py-4 px-4 text-right space-x-1.5\">\n        <button onclick=\"renewClient(${c.id})\" class=\"bg-emerald-600 hover:bg-emerald-700 text-white font-extrabold text-xs px-3 py-2 rounded-xl shadow-sm transition inline-flex items-center gap-1\">\n          <i class=\"fa-solid fa-circle-check\"></i> Baixa\n        </button>\n        <button onclick=\"openQuickMessageModal(${c.id})\" class=\"bg-brand-blue hover:bg-sky-700 text-white font-extrabold text-xs px-3 py-2 rounded-xl shadow-sm transition inline-flex items-center gap-1\">\n          <i class=\"fa-brands fa-whatsapp\"></i> Aviso\n        </button>\n        <button onclick=\"editClient(${c.id})\" class=\"text-slate-600 hover:text-brand-blue p-2 font-bold text-base\"><i class=\"fa-solid fa-pen-to-square\"></i></button>\n        <button onclick=\"deleteClient(${c.id})\" class=\"text-slate-600 hover:text-red-600 p-2 font-bold text-base\"><i class=\"fa-solid fa-trash\"></i></button>\n      </td>\n    `;\n\n    tbody.appendChild(tr);\n  });\n}\n\nfunction filterClients() {\n  const input = document.getElementById('searchClientInput');\n  const select = document.getElementById('filterStatusSelect');\n  if (!input || !select) return;\n\n  const query = input.value.toLowerCase().trim();\n  const status = select.value;\n\n  const filtered = allClients.filter(c => {\n    const code = (c.client_code || `#${1000 + c.id}`).toLowerCase();\n    const app = (c.app_name || '').toLowerCase();\n    const server = (c.server_name || '').toLowerCase();\n\n    const matchesSearch = c.name.toLowerCase().includes(query) || c.phone.includes(query) || c.plan_name.toLowerCase().includes(query) || code.includes(query) || app.includes(query) || server.includes(query);\n    \n    const today = new Date().toISOString().split('T')[0];\n    const due = new Date(c.due_date + 'T00:00:00');\n    const now = new Date(today + 'T00:00:00');\n    const diffDays = Math.ceil((due - now) / (1000 * 60 * 60 * 24));\n\n    let matchesStatus = true;\n    if (status === 'active') matchesStatus = (diffDays > 3);\n    if (status === 'expiring') matchesStatus = (diffDays >= 0 && diffDays <= 3);\n    if (status === 'expired') matchesStatus = (diffDays < 0);\n\n    return matchesSearch && matchesStatus;\n  });\n\n  renderClients(filtered);\n}\n\nfunction updateDashboardStats(clients) {\n  const total = clients.length;\n  const today = new Date().toISOString().split('T')[0];\n\n  let active = 0;\n  let expiring = 0;\n  let expired = 0;\n  let revenue = 0;\n\n  const oneDayList = [];\n  const expiredList = [];\n\n  clients.forEach(c => {\n    revenue += parseFloat(c.price || 0);\n\n    const due = new Date(c.due_date + 'T00:00:00');\n    const now = new Date(today + 'T00:00:00');\n    const diffDays = Math.ceil((due - now) / (1000 * 60 * 60 * 24));\n\n    if (diffDays < 0) {\n      expired++;\n      expiredList.push({ ...c, diffDays });\n    } else if (diffDays <= 3) {\n      expiring++;\n      if (diffDays <= 1) {\n        oneDayList.push({ ...c, diffDays });\n      }\n    } else {\n      active++;\n    }\n  });\n\n  if (document.getElementById('statTotalClients')) document.getElementById('statTotalClients').innerText = total;\n  if (document.getElementById('statActiveClients')) document.getElementById('statActiveClients').innerText = active;\n  if (document.getElementById('statExpiringClients')) document.getElementById('statExpiringClients').innerText = expiring;\n  if (document.getElementById('statExpiredClients')) document.getElementById('statExpiredClients').innerText = expired;\n  if (document.getElementById('statMonthlyRevenue')) document.getElementById('statMonthlyRevenue').innerText = `R$ ${revenue.toFixed(2)}`;\n\n  // RENDERIZAR ALERTAS URGENTES NO DASHBOARD\n  const oneDayBox = document.getElementById('alertOneDayBox');\n  const oneDayListDiv = document.getElementById('alertOneDayList');\n  const oneDayCountSpan = document.getElementById('alertOneDayCount');\n\n  if (oneDayList.length > 0) {\n    oneDayBox.classList.remove('hidden');\n    oneDayCountSpan.innerText = `${oneDayList.length} Cliente(s)`;\n    oneDayListDiv.innerHTML = '';\n    oneDayList.forEach(c => {\n      const item = document.createElement('div');\n      item.className = 'bg-white p-3.5 rounded-xl border border-amber-300 flex items-center justify-between';\n      const dueDateFormatted = c.due_date ? c.due_date.split('-').reverse().join('/') : '-';\n      item.innerHTML = `\n        <div>\n          <span class=\"font-extrabold text-slate-900 text-base\">${c.name}</span>\n          <span class=\"text-xs font-mono text-amber-800 bg-amber-100 px-2 py-0.5 rounded font-bold ml-2\">Vence: ${dueDateFormatted} (${c.diffDays === 0 ? 'HOJE' : 'AMANHÃ'})</span>\n          <p class=\"text-xs text-slate-600\">${c.plan_name} - R$ ${parseFloat(c.price).toFixed(2)}</p>\n        </div>\n        <div class=\"flex items-center space-x-2\">\n          <button onclick=\"openQuickMessageModal(${c.id}, 'tomorrow')\" class=\"bg-amber-600 hover:bg-amber-700 text-white font-bold text-xs px-3.5 py-2 rounded-xl shadow-sm transition\">\n            <i class=\"fa-brands fa-whatsapp\"></i> Aviso 1D\n          </button>\n          <button onclick=\"renewClient(${c.id})\" class=\"bg-emerald-600 hover:bg-emerald-700 text-white font-bold text-xs px-3.5 py-2 rounded-xl shadow-sm transition\">\n            Dar Baixa\n          </button>\n        </div>\n      `;\n      oneDayListDiv.appendChild(item);\n    });\n  } else if (oneDayBox) {\n    oneDayBox.classList.add('hidden');\n  }\n\n  const expiredBox = document.getElementById('alertExpiredBox');\n  const expiredListDiv = document.getElementById('alertExpiredList');\n  const expiredCountSpan = document.getElementById('alertExpiredCount');\n\n  if (expiredList.length > 0) {\n    expiredBox.classList.remove('hidden');\n    expiredCountSpan.innerText = `${expiredList.length} Cliente(s)`;\n    expiredListDiv.innerHTML = '';\n    expiredList.forEach(c => {\n      const item = document.createElement('div');\n      item.className = 'bg-white p-3.5 rounded-xl border border-red-300 flex items-center justify-between';\n      const dueDateFormatted = c.due_date ? c.due_date.split('-').reverse().join('/') : '-';\n      item.innerHTML = `\n        <div>\n          <span class=\"font-extrabold text-slate-900 text-base\">${c.name}</span>\n          <span class=\"text-xs font-mono text-red-700 bg-red-100 px-2 py-0.5 rounded font-bold ml-2\">Venceu em: ${dueDateFormatted}</span>\n          <p class=\"text-xs text-slate-600\">${c.plan_name} - R$ ${parseFloat(c.price).toFixed(2)}</p>\n        </div>\n        <div class=\"flex items-center space-x-2\">\n          <button onclick=\"openQuickMessageModal(${c.id}, 'expired')\" class=\"bg-red-600 hover:bg-red-700 text-white font-bold text-xs px-3.5 py-2 rounded-xl shadow-sm transition\">\n            <i class=\"fa-brands fa-whatsapp\"></i> Aviso Atraso\n          </button>\n          <button onclick=\"renewClient(${c.id})\" class=\"bg-emerald-600 hover:bg-emerald-700 text-white font-bold text-xs px-3.5 py-2 rounded-xl shadow-sm transition\">\n            Dar Baixa\n          </button>\n        </div>\n      `;\n      expiredListDiv.appendChild(item);\n    });\n  } else if (expiredBox) {\n    expiredBox.classList.add('hidden');\n  }\n}\n\n// === MODAL CLIENTE (CADASTRO E EDIÇÃO COM SELEÇÃO DE APP E SERVIDOR) ===\nfunction openClientModal(editId = null) {\n  document.getElementById('clientId').value = '';\n  document.getElementById('clientName').value = '';\n  document.getElementById('clientPhone').value = '';\n  document.getElementById('clientPlanName').value = 'IPTV Premium 1 Tela';\n  document.getElementById('clientPrice').value = '35.00';\n  document.getElementById('clientNotes').value = '';\n  document.getElementById('clientStatus').value = 'active';\n  document.getElementById('clientAppSelect').value = '';\n  document.getElementById('clientServerSelect').value = '';\n\n  // Data de hoje + 30 dias por padrão\n  const nextMonth = new Date();\n  nextMonth.setDate(nextMonth.getDate() + 30);\n  document.getElementById('clientDueDate').value = nextMonth.toISOString().split('T')[0];\n\n  const titleEl = document.getElementById('clientModalTitle');\n\n  if (editId) {\n    const client = allClients.find(c => c.id === editId);\n    if (client) {\n      if (titleEl) titleEl.innerText = 'Editar Cliente IPTV';\n      document.getElementById('clientId').value = client.id;\n      document.getElementById('clientName').value = client.name;\n      document.getElementById('clientPhone').value = client.phone;\n      document.getElementById('clientPlanName').value = client.plan_name;\n      document.getElementById('clientPrice').value = client.price;\n      document.getElementById('clientDueDate').value = client.due_date;\n      document.getElementById('clientStatus').value = client.status || 'active';\n      document.getElementById('clientNotes').value = client.notes || '';\n      document.getElementById('clientAppSelect').value = client.app_name || '';\n      document.getElementById('clientServerSelect').value = client.server_name || '';\n    }\n  } else {\n    if (titleEl) titleEl.innerText = 'Cadastrar Novo Cliente';\n  }\n\n  document.getElementById('clientModal').classList.remove('hidden');\n}\n\nfunction closeClientModal() {\n  document.getElementById('clientModal').classList.add('hidden');\n}\n\nfunction editClient(id) {\n  openClientModal(id);\n}\n\nasync function saveClient(e) {\n  e.preventDefault();\n  const id = document.getElementById('clientId').value;\n  const clientData = {\n    name: document.getElementById('clientName').value.trim(),\n    phone: document.getElementById('clientPhone').value.trim(),\n    plan_name: document.getElementById('clientPlanName').value.trim(),\n    price: parseFloat(document.getElementById('clientPrice').value),\n    due_date: document.getElementById('clientDueDate').value,\n    status: document.getElementById('clientStatus').value,\n    notes: document.getElementById('clientNotes').value.trim(),\n    app_name: document.getElementById('clientAppSelect').value,\n    server_name: document.getElementById('clientServerSelect').value\n  };\n\n  try {\n    let res;\n    if (id) {\n      res = await fetch(`/api/clients/${id}`, {\n        method: 'PUT',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify(clientData)\n      });\n    } else {\n      res = await fetch('/api/clients', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify(clientData)\n      });\n    }\n\n    if (!res.ok) throw new Error('Erro ao salvar dados do cliente');\n\n    closeClientModal();\n    loadClients();\n    alert('Cliente salvo com sucesso!');\n  } catch (err) {\n    alert('Erro ao salvar cliente: ' + err.message);\n  }\n}\n\nasync function deleteClient(id) {\n  if (!confirm('Tem certeza que deseja excluir este cliente?')) return;\n\n  try {\n    await fetch(`/api/clients/${id}`, { method: 'DELETE' });\n    loadClients();\n  } catch (e) {\n    alert('Erro ao excluir cliente: ' + e.message);\n  }\n}\n\n// === DAR BAIXA / RENOVAR PLANO POR +30 DIAS ===\n// === DAR BAIXA / RENOVAR PLANO POR +30 DIAS ===\nasync function renewClient(id) {\n  try {\n    const res = await fetch(`/api/clients/${id}/renew`, { method: 'POST' });\n    const data = await res.json();\n\n    if (data.success) {\n      loadClients();\n      await loadReceipts();\n      if (data.receipt && data.receipt.id) {\n        viewReceiptDetails(data.receipt.id);\n      }\n    }\n  } catch (e) {\n    alert('Erro ao dar baixa no plano: ' + e.message);\n  }\n}\n\n// === GERENCIADOR DE RECIBOS PROFISSIONAIS & HISTÓRICO ===\nlet allReceipts = [];\nlet activeReceiptObj = null;\n\nasync function loadReceipts() {\n  try {\n    const res = await fetch('/api/receipts');\n    allReceipts = await res.json();\n    renderReceiptsTable(allReceipts);\n  } catch (e) {\n    console.error('Erro ao carregar recibos:', e);\n  }\n}\n\nfunction renderReceiptsTable(receipts) {\n  const tbody = document.getElementById('receiptsTableBody');\n  if (!tbody) return;\n  tbody.innerHTML = '';\n\n  if (!receipts || receipts.length === 0) {\n    tbody.innerHTML = `<tr><td colspan=\"7\" class=\"py-8 text-center text-slate-500 font-bold text-base\">Nenhum recibo de renovação gerado ainda.</td></tr>`;\n    return;\n  }\n\n  receipts.forEach(r => {\n    const tr = document.createElement('tr');\n    tr.className = 'hover:bg-amber-50/80 transition border-b border-[#e2d7c5] cursor-pointer';\n\n    const dueFormatted = r.next_due_date ? r.next_due_date.split('-').reverse().join('/') : '-';\n    const priceFormatted = parseFloat(r.price).toFixed(2);\n\n    tr.innerHTML = `\n      <td onclick=\"viewReceiptDetails(${r.id})\" class=\"py-3.5 px-4 font-mono font-extrabold text-brand-orange text-sm\">\n        ${r.receipt_code}\n      </td>\n      <td onclick=\"viewReceiptDetails(${r.id})\" class=\"py-3.5 px-4 font-bold text-slate-900 text-base\">\n        ${r.client_name}\n      </td>\n      <td onclick=\"viewReceiptDetails(${r.id})\" class=\"py-3.5 px-4 text-slate-700 font-medium\">\n        ${r.plan_name}\n      </td>\n      <td onclick=\"viewReceiptDetails(${r.id})\" class=\"py-3.5 px-4 font-extrabold text-emerald-700\">\n        R$ ${priceFormatted}\n      </td>\n      <td onclick=\"viewReceiptDetails(${r.id})\" class=\"py-3.5 px-4 text-slate-600 font-medium\">\n        ${r.renewed_at}\n      </td>\n      <td onclick=\"viewReceiptDetails(${r.id})\" class=\"py-3.5 px-4\">\n        <span class=\"bg-emerald-100 text-emerald-800 border border-emerald-300 px-3 py-1 rounded-full text-xs font-extrabold\">\n          🟢 ${dueFormatted}\n        </span>\n      </td>\n      <td class=\"py-3.5 px-4 text-right space-x-1.5 whitespace-nowrap\" onclick=\"event.stopPropagation()\">\n        <button onclick=\"viewReceiptDetails(${r.id})\" class=\"bg-brand-blue hover:bg-sky-700 text-white font-bold text-xs px-3 py-2 rounded-xl shadow-sm transition\">\n          <i class=\"fa-solid fa-eye\"></i> Ver Recibo\n        </button>\n        <button onclick=\"openEditReceiptModal(${r.id})\" class=\"bg-amber-600 hover:bg-amber-700 text-white font-bold text-xs px-3 py-2 rounded-xl shadow-sm transition\">\n          <i class=\"fa-solid fa-pen\"></i> Editar\n        </button>\n        <button onclick=\"deleteReceiptById(${r.id})\" class=\"bg-red-600 hover:bg-red-700 text-white font-bold text-xs px-3 py-2 rounded-xl shadow-sm transition\">\n          <i class=\"fa-solid fa-trash\"></i> Excluir\n        </button>\n        <button onclick=\"resendReceiptWhatsapp(${r.id})\" class=\"bg-emerald-600 hover:bg-emerald-700 text-white font-bold text-xs px-3 py-2 rounded-xl shadow-sm transition\">\n          <i class=\"fa-brands fa-whatsapp\"></i> Reenviar\n        </button>\n      </td>\n    `;\n    tbody.appendChild(tr);\n  });\n}\n\nasync function viewReceiptDetails(id) {\n  console.log('🔍 viewReceiptDetails acionado para ID:', id);\n\n  let r = null;\n  if (Array.isArray(allReceipts) && allReceipts.length > 0) {\n    r = allReceipts.find(rec => rec.id == id);\n  }\n\n  if (!r) {\n    try {\n      const res = await fetch('/api/receipts');\n      allReceipts = await res.json();\n      r = allReceipts.find(rec => rec.id == id);\n    } catch (err) {\n      console.error('Erro ao buscar recibos do servidor:', err);\n    }\n  }\n\n  if (!r) {\n    alert('Recibo de ID ' + id + ' não foi encontrado no banco de dados. Atualizando lista...');\n    loadReceipts();\n    return;\n  }\n\n  activeReceiptObj = r;\n\n  const company = currentSettings.company_name || 'GN IPTV';\n  const logoUrl = currentSettings.company_logo || '';\n  const dueFormatted = r.next_due_date ? String(r.next_due_date).split('-').reverse().join('/') : '-';\n  const priceFormatted = r.price ? parseFloat(r.price).toFixed(2) : '0.00';\n\n  const companyNameEl = document.getElementById('receiptCompanyName');\n  if (companyNameEl) companyNameEl.innerText = company;\n\n  const codeBadgeEl = document.getElementById('receiptCodeBadge');\n  if (codeBadgeEl) codeBadgeEl.innerText = r.receipt_code || `REC-${r.id}`;\n\n  const clientNameEl = document.getElementById('receiptClientNameText');\n  if (clientNameEl) clientNameEl.innerText = r.client_name || '-';\n\n  const planNameEl = document.getElementById('receiptPlanNameText');\n  if (planNameEl) planNameEl.innerText = r.plan_name || '-';\n\n  const priceTextEl = document.getElementById('receiptPriceText');\n  if (priceTextEl) priceTextEl.innerText = `R$ ${priceFormatted}`;\n\n  const dateTextEl = document.getElementById('receiptDateText');\n  if (dateTextEl) dateTextEl.innerText = r.renewed_at || '-';\n\n  const nextDueTextEl = document.getElementById('receiptNextDueText');\n  if (nextDueTextEl) nextDueTextEl.innerText = dueFormatted;\n\n  const logoBox = document.getElementById('receiptLogoBox');\n  if (logoBox) {\n    if (logoUrl && logoUrl.trim().length > 3) {\n      logoBox.innerHTML = `<img src=\"${logoUrl}\" alt=\"Logo\" class=\"w-full h-full object-contain\">`;\n    } else {\n      logoBox.innerHTML = `<i class=\"fa-solid fa-tv text-amber-400 text-2xl\"></i>`;\n    }\n  }\n\n  currentReceiptPhone = r.phone || '';\n  currentReceiptText = `🧾 *RECIBO DE RENOVAÇÃO DE PLANO IPTV*\n----------------------------------------\nEmpresa: *${company}*\nCódigo do Recibo: *${r.receipt_code || `REC-${r.id}`}*\nData do Pagamento: *${r.renewed_at || '-'}*\n\nCliente: *${r.client_name || '-'}*\nPlano: *${r.plan_name || '-'}*\nValor Pago: *R$ ${priceFormatted}*\n\n🗓 *PRÓXIMO VENCIMENTO*: *${dueFormatted}* (Renovado por +30 dias)\n----------------------------------------\nObrigado pela preferência e ótimo entretenimento! 🍿📺`;\n\n  const boxContent = document.getElementById('receiptBoxContent');\n  if (boxContent) boxContent.innerText = currentReceiptText;\n\n  const receiptModal = document.getElementById('receiptModal');\n  if (receiptModal) {\n    receiptModal.classList.remove('hidden');\n    receiptModal.style.setProperty('display', 'flex', 'important');\n    receiptModal.style.zIndex = '99999';\n  } else {\n    alert('Erro: Elemento #receiptModal não encontrado no HTML.');\n  }\n}\n\nfunction resendReceiptWhatsapp(id) {\n  const r = allReceipts.find(rec => rec.id == id);\n  if (!r) return;\n  viewReceiptDetails(id);\n  if (r.phone) {\n    sendReceiptViaWhatsapp();\n  } else {\n    alert('Telefone do cliente não encontrado na base. Utilize a opção de copiar texto.');\n  }\n}\n\nasync function deleteReceiptById(id) {\n  if (!confirm('Tem certeza que deseja excluir este recibo do histórico?')) return;\n  try {\n    await fetch(`/api/receipts/${id}`, { method: 'DELETE' });\n    alert('Recibo excluído com sucesso!');\n    closeReceiptModal();\n    loadReceipts();\n  } catch (e) {\n    alert('Erro ao excluir recibo: ' + e.message);\n  }\n}\n\nfunction deleteCurrentActiveReceipt() {\n  if (activeReceiptObj && activeReceiptObj.id) {\n    deleteReceiptById(activeReceiptObj.id);\n  } else {\n    closeReceiptModal();\n  }\n}\n\nasync function openEditReceiptModal(id) {\n  let r = allReceipts.find(rec => rec.id == id);\n  if (!r) {\n    try {\n      const res = await fetch('/api/receipts');\n      allReceipts = await res.json();\n      r = allReceipts.find(rec => rec.id == id);\n    } catch (e) {}\n  }\n\n  if (!r) {\n    alert('Recibo de ID ' + id + ' não foi encontrado no banco de dados para edição.');\n    return;\n  }\n\n  const editId = document.getElementById('editReceiptId');\n  const editCode = document.getElementById('editReceiptCode');\n  const editClient = document.getElementById('editReceiptClientName');\n  const editPlan = document.getElementById('editReceiptPlanName');\n  const editPrice = document.getElementById('editReceiptPrice');\n  const editRenewed = document.getElementById('editReceiptRenewedAt');\n  const editNext = document.getElementById('editReceiptNextDue');\n\n  if (editId) editId.value = r.id;\n  if (editCode) editCode.value = r.receipt_code || '';\n  if (editClient) editClient.value = r.client_name || '';\n  if (editPlan) editPlan.value = r.plan_name || '';\n  if (editPrice) editPrice.value = r.price || 0;\n  if (editRenewed) editRenewed.value = r.renewed_at || '';\n  if (editNext) editNext.value = r.next_due_date || '';\n\n  const modal = document.getElementById('editReceiptModal');\n  if (modal) {\n    modal.classList.remove('hidden');\n    modal.style.setProperty('display', 'flex', 'important');\n    modal.style.zIndex = '99999';\n  } else {\n    alert('Erro: Modal #editReceiptModal não encontrado no HTML.');\n  }\n}\n\nfunction closeEditReceiptModal() {\n  const modal = document.getElementById('editReceiptModal');\n  if (modal) {\n    modal.classList.add('hidden');\n    modal.style.display = 'none';\n  }\n}\n\nfunction closeReceiptModal() {\n  const modal = document.getElementById('receiptModal');\n  if (modal) {\n    modal.classList.add('hidden');\n    modal.style.display = 'none';\n  }\n}\n\nasync function saveEditedReceipt(e) {\n  e.preventDefault();\n  const id = document.getElementById('editReceiptId').value;\n  const data = {\n    receipt_code: document.getElementById('editReceiptCode').value.trim(),\n    client_name: document.getElementById('editReceiptClientName').value.trim(),\n    plan_name: document.getElementById('editReceiptPlanName').value.trim(),\n    price: parseFloat(document.getElementById('editReceiptPrice').value),\n    renewed_at: document.getElementById('editReceiptRenewedAt').value.trim(),\n    next_due_date: document.getElementById('editReceiptNextDue').value\n  };\n\n  try {\n    const res = await fetch(`/api/receipts/${id}`, {\n      method: 'PUT',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify(data)\n    });\n    if (!res.ok) throw new Error('Erro ao atualizar recibo');\n    alert('Recibo alterado com sucesso!');\n    closeEditReceiptModal();\n    loadReceipts();\n    if (activeReceiptObj && activeReceiptObj.id == id) {\n      viewReceiptDetails(parseInt(id));\n    }\n  } catch (err) {\n    alert('Erro ao salvar recibo: ' + err.message);\n  }\n}\n\nfunction printVisualReceipt() {\n  const printContent = document.getElementById('receiptVisualCard').outerHTML;\n  const win = window.open('', '', 'width=600,height=700');\n  const sEnd = '</' + 'script>';\n  win.document.write(`\n    <html>\n      <head>\n        <title>Recibo de Renovação</title>\n        <script src=\"https://cdn.tailwindcss.com\">${sEnd}\n        <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\">\n      </head>\n      <body class=\"p-8 bg-slate-100 flex items-center justify-center min-h-screen\">\n        <div class=\"w-full max-w-md\">\n          ${printContent}\n        </div>\n        <script>\n          setTimeout(() => { window.close(); }, 500);\n        ${sEnd}\n      </body>\n    </html>\n  `);\n  win.document.close();\n}\n\nfunction closeReceiptModal() {\n  const modal = document.getElementById('receiptModal');\n  if (modal) modal.classList.add('hidden');\n}\n\nfunction copyReceiptText() {\n  navigator.clipboard.writeText(currentReceiptText);\n  alert('📋 Recibo copiado para a área de transferência!');\n}\n\nfunction sendReceiptViaWhatsapp() {\n  const encodedText = encodeURIComponent(currentReceiptText);\n  window.open(`https://wa.me/${currentReceiptPhone}?text=${encodedText}`, '_blank');\n}\n\n// === MODAL MENSAGEM RÁPIDA WHATSAPP ===\nfunction openQuickMessageModal(clientId, defaultTemplate = 'today') {\n  const client = allClients.find(c => c.id === clientId);\n  if (!client) return;\n\n  currentQuickClient = client;\n\n  document.getElementById('qmClientName').innerText = client.name;\n  document.getElementById('qmClientPhone').innerText = client.phone;\n  document.getElementById('qmTemplateSelect').value = defaultTemplate;\n\n  updateQuickMessagePreview();\n  document.getElementById('quickMessageModal').classList.remove('hidden');\n}\n\nfunction closeQuickMessageModal() {\n  document.getElementById('quickMessageModal').classList.add('hidden');\n}\n\nfunction updateQuickMessagePreview() {\n  if (!currentQuickClient) return;\n\n  const tpl = document.getElementById('qmTemplateSelect').value;\n  const company = currentSettings.company_name || 'IPTV Premium';\n  const pixKey = currentSettings.pix_key || '11985897774';\n  const dueFormatted = currentQuickClient.due_date ? currentQuickClient.due_date.split('-').reverse().join('/') : '-';\n  const priceFormatted = parseFloat(currentQuickClient.price).toFixed(2);\n\n  let msg = '';\n\n  if (tpl === 'today') {\n    msg = `🗓 *LEMBRETE DE VENCIMENTO - ${company}*\\n\\nOlá, *${currentQuickClient.name}*! 👋\\nLembramos que a mensalidade do seu plano *${currentQuickClient.plan_name}* vence **HOJE** (${dueFormatted}).\\n\\n💰 Valor: R$ ${priceFormatted}\\n🔑 Chave PIX: \\`${pixKey}\\`\\n\\nPara manter sua transmissão ativa sem interrupções, realize o Pix e nos envie o comprovante por aqui! 😊`;\n  } else if (tpl === 'tomorrow') {\n    msg = `⏳ *LEMBRETE DE VENCIMENTO - ${company}*\\n\\nOlá, *${currentQuickClient.name}*! 👋\\nPassando para lembrar que o seu plano *${currentQuickClient.plan_name}* vence **AMANHÃ** (${dueFormatted}).\\n\\n💰 Valor: R$ ${priceFormatted}\\n🔑 Chave PIX: \\`${pixKey}\\`\\n\\nGaranta sua renovação antecipada e continue aproveitando todos os canais sem travamentos! 🚀`;\n  } else if (tpl === 'expired') {\n    msg = `🔴 *AVISO DE PLANO ATRASADO / SUSPENSO - ${company}*\\n\\nOlá, *${currentQuickClient.name}*! 👋\\nIdentificamos que o seu plano *${currentQuickClient.plan_name}* venceu em ${dueFormatted} e encontra-se suspenso.\\n\\n💰 Valor: R$ ${priceFormatted}\\n🔑 Chave PIX para Reativação: \\`${pixKey}\\`\\n\\nEnvie o comprovante assim que realizar o pagamento para reativarmos seu sinal imediatamente! 🍿`;\n  } else if (tpl === 'renewed') {\n    msg = `🎉 *RENOVAÇÃO CONFIRMADA COM SUCESSO!*\\n\\nOlá, *${currentQuickClient.name}*! 👋\\nConfirmamos a renovação do seu plano *${currentQuickClient.plan_name}*!\\n\\n🗓 Próximo Vencimento: *${dueFormatted}*\\n💰 Valor: R$ ${priceFormatted}\\n\\nAgradecemos a preferência e desejamos um excelente entretenimento! 📺🍿`;\n  }\n\n  document.getElementById('qmMessageText').value = msg;\n}\n\nasync function sendQuickMessageSocket() {\n  if (!currentQuickClient) return;\n  const text = document.getElementById('qmMessageText').value.trim();\n\n  if (!text) {\n    alert('Digite a mensagem a ser enviada.');\n    return;\n  }\n\n  try {\n    const res = await fetch('/api/whatsapp/send-message', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ phone: currentQuickClient.phone, message: text })\n    });\n    const data = await res.json();\n    alert('🤖 Mensagem enviada pelo robô do WhatsApp com sucesso!');\n    closeQuickMessageModal();\n  } catch (err) {\n    alert('Erro ao enviar mensagem: ' + err.message);\n  }\n}\n\nfunction openQuickMessageWhatsAppWeb() {\n  if (!currentQuickClient) return;\n  const text = document.getElementById('qmMessageText').value.trim();\n  const url = `https://wa.me/${currentQuickClient.phone}?text=${encodeURIComponent(text)}`;\n  window.open(url, '_blank');\n}\n\n// === RECIBOS & DISPAROS ===\nasync function loadReceipts() {\n  try {\n    const res = await fetch('/api/receipts');\n    const receipts = await res.json();\n    \n    const tbody = document.getElementById('receiptsTableBody');\n    if (!tbody) return;\n    tbody.innerHTML = '';\n\n    if (!receipts || receipts.length === 0) {\n      tbody.innerHTML = `<tr><td colspan=\"7\" class=\"text-center py-6 text-slate-500 font-medium\">Nenhum recibo gerado ainda. Dar baixa num plano gera o recibo automaticamente.</td></tr>`;\n      return;\n    }\n\n    receipts.forEach(r => {\n      const tr = document.createElement('tr');\n      tr.className = 'hover:bg-amber-50/80 transition border-b border-[#e2d7c5]';\n      \n      const nextDueFormatted = r.next_due_date.split('-').reverse().join('/');\n\n      tr.innerHTML = `\n        <td class=\"py-3 px-4 font-mono text-brand-orange font-bold text-xs\">${r.receipt_code}</td>\n        <td class=\"py-3 px-4 font-semibold text-slate-900\">${r.client_name}</td>\n        <td class=\"py-3 px-4 text-slate-700\">${r.plan_name}</td>\n        <td class=\"py-3 px-4 font-extrabold text-emerald-600\">R$ ${parseFloat(r.price).toFixed(2)}</td>\n        <td class=\"py-3 px-4 text-slate-600\">${r.renewed_at}</td>\n        <td class=\"py-3 px-4 font-bold text-slate-900\">🗓 ${nextDueFormatted}</td>\n        <td class=\"py-3 px-4 text-right\">\n          <button onclick=\"viewReceiptFromTable('${r.receipt_code}', '${r.client_name}', '${r.plan_name}', ${r.price}, '${r.renewed_at}', '${r.next_due_date}')\" class=\"text-xs text-brand-blue hover:underline font-bold\">Ver Recibo</button>\n        </td>\n      `;\n\n      tbody.appendChild(tr);\n    });\n  } catch (e) {\n    console.error('Erro ao carregar recibos:', e);\n  }\n}\n\n// === PWA & RECURSOS DE INSTALAÇÃO DO APLICATIVO ===\nlet deferredPrompt = null;\n\nwindow.addEventListener('beforeinstallprompt', (e) => {\n  e.preventDefault();\n  deferredPrompt = e;\n  const banner = document.getElementById('pwaInstallBanner');\n  const topBtn = document.getElementById('pwaInstallBtnTop');\n  if (banner) banner.classList.remove('hidden');\n  if (topBtn) topBtn.classList.remove('hidden');\n});\n\nasync function triggerPwaInstall() {\n  if (!deferredPrompt) {\n    alert('📱 Para instalar o Aplicativo:\\n\\n' +\n          '• No Android (Chrome): Clique no menu de 3 pontos no topo e em \"Adicionar à Tela Inicial\" ou \"Instalar Aplicativo\".\\n' +\n          '• No iPhone (Safari): Clique no botão Compartilhar 📤 e selecione \"Adicionar à Tela de Início\".\\n' +\n          '• No Computador (Chrome/Edge): Clique no ícone de instalar na barra de endereço do navegador.');\n    return;\n  }\n  deferredPrompt.prompt();\n  const { outcome } = await deferredPrompt.userChoice;\n  if (outcome === 'accepted') {\n    console.log('Usuário aceitou a instalação do App!');\n  }\n  deferredPrompt = null;\n  closePwaBanner();\n}\n\nfunction closePwaBanner() {\n  const banner = document.getElementById('pwaInstallBanner');\n  if (banner) banner.classList.add('hidden');\n}\n\n// Registrar Service Worker para PWA\nif ('serviceWorker' in navigator) {\n  window.addEventListener('load', () => {\n    navigator.serviceWorker.register('/sw.js')\n      .then(reg => console.log('Service Worker registrado com sucesso:', reg.scope))\n      .catch(err => console.error('Erro ao registrar Service Worker:', err));\n  });\n}\n";